// Top-level Am9512 directed/random vector regression.
// The vectors are generated by scripts/gen_vectors.py, an independent model
// derived from the 1980 AMD Am9500 guide.  This testbench only drives the bus
// and compares the external stack, status and handshake outputs.
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "Vamd_am9512.h"
#include "verilated.h"

static Vamd_am9512 *top;
static uint64_t tick_count = 0;

static void tick() {
    top->clk_i = 0;
    top->eval();
    top->clk_i = 1;
    top->eval();
    ++tick_count;
}

static void idle_inputs() {
    top->cs_n_i = 1;
    top->rd_n_i = 1;
    top->wr_n_i = 1;
    top->cd_i = 0;
    top->eack_n_i = 1;
    top->svack_n_i = 1;
    top->data_i = 0;
}

static void reset_chip() {
    idle_inputs();
    top->reset_i = 1;
    for (int i = 0; i < 8; ++i)
        tick();
    top->reset_i = 0;
    for (int i = 0; i < 2; ++i)
        tick();
}

static bool write_cycle(uint8_t value, bool command, int *pause_low_cycles = nullptr) {
    top->cs_n_i = 0;
    top->rd_n_i = 1;
    top->wr_n_i = 1;
    top->cd_i = command ? 1 : 0;
    top->data_i = value;
    tick();
    int low = 0;
    while (!top->pause_n_o && low < 100) {
        tick();
        ++low;
    }
    if (pause_low_cycles)
        *pause_low_cycles = low;
    top->wr_n_i = 0;
    int wait = 0;
    while (!top->pause_n_o && wait < 100) {
        tick();
        ++wait;
    }
    top->wr_n_i = 1;
    top->cs_n_i = 1;
    return top->pause_n_o;
}

static uint8_t read_cycle(bool status) {
    top->cs_n_i = 0;
    top->rd_n_i = 1;
    top->wr_n_i = 1;
    top->cd_i = status ? 1 : 0;
    tick();
    top->rd_n_i = 0;
    uint8_t value = 0;
    int wait = 0;
    while (!top->pause_n_o && wait < 100) {
        tick();
        ++wait;
    }
    if (top->pause_n_o)
        value = top->data_o;
    top->rd_n_i = 1;
    top->cs_n_i = 1;
    return value;
}

static bool wait_end(int max_cycles) {
    for (int i = 0; i < max_cycles; ++i) {
        if (top->end_o)
            return true;
        tick();
    }
    return false;
}

static int hex_nibble(char c) {
    if (c >= '0' && c <= '9')
        return c - '0';
    if (c >= 'a' && c <= 'f')
        return c - 'a' + 10;
    if (c >= 'A' && c <= 'F')
        return c - 'A' + 10;
    return -1;
}

static bool parse_hex(const std::string &text, std::vector<uint8_t> &out) {
    if (text.size() % 2 != 0)
        return false;
    out.clear();
    for (size_t i = 0; i < text.size(); i += 2) {
        int hi = hex_nibble(text[i]);
        int lo = hex_nibble(text[i + 1]);
        if (hi < 0 || lo < 0)
            return false;
        out.push_back(static_cast<uint8_t>((hi << 4) | lo));
    }
    return true;
}

int main(int argc, char **argv) {
    Verilated::commandArgs(argc, argv);
    std::string path = "design/amd_am9512/work/vectors.txt";
    if (argc > 1)
        path = argv[1];

    std::ifstream file(path);
    if (!file) {
        std::cerr << "cannot open " << path << "\n";
        return 1;
    }

    top = new Vamd_am9512;
    top->clk_i = 0;
    top->reset_i = 0;
    idle_inputs();
    top->eval();
    reset_chip();

    int failures = 0;
    int tests = 0;
    std::string line;
    while (std::getline(file, line)) {
        if (line.empty() || line[0] == '#')
            continue;
        std::istringstream stream(line);
        std::string op_text, stack_text, expected_text, status_text, name;
        if (!(stream >> op_text >> stack_text >> expected_text >> status_text)) {
            std::cerr << "bad vector line: " << line << "\n";
            return 1;
        }
        std::getline(stream, name);
        uint8_t op = static_cast<uint8_t>(std::stoul(op_text, nullptr, 16));
        std::vector<uint8_t> initial, expected;
        if (!parse_hex(stack_text, initial) || initial.size() != 16 ||
            !parse_hex(expected_text, expected) || expected.size() != 16) {
            std::cerr << "bad hex vector: " << line << "\n";
            return 1;
        }
        uint8_t expected_status = static_cast<uint8_t>(std::stoul(status_text, nullptr, 16));
        ++tests;

        // Load the stack by writing the desired top-to-bottom bytes in reverse.
        for (int i = 15; i >= 0; --i) {
            if (!write_cycle(initial[i], false)) {
                std::cerr << "FAIL " << name << ": stack preload write did not acknowledge\n";
                ++failures;
                break;
            }
        }

        if (!write_cycle(op, true)) {
            std::cerr << "FAIL " << name << ": command write did not acknowledge\n";
            ++failures;
            continue;
        }
        if (!wait_end(20000)) {
            std::cerr << "FAIL " << name << ": command did not complete\n";
            ++failures;
            continue;
        }
        bool end_seen = top->end_o != 0;
        bool err_seen = top->err_o != 0;
        bool svreq_seen = top->svreq_o != 0;

        std::vector<uint8_t> actual;
        for (int i = 0; i < 16; ++i)
            actual.push_back(read_cycle(false));
        uint8_t actual_status = read_cycle(true);

        // Clear a latched service request for the next vector.
        top->svack_n_i = 0;
        tick();
        top->svack_n_i = 1;
        tick();

        bool ok = true;
        if (!end_seen) {
            std::cerr << "FAIL " << name << ": END not asserted\n";
            ok = false;
        }
        bool expected_err = (expected_status & 0x0E) != 0;
        if (err_seen != expected_err) {
            std::cerr << "FAIL " << name << ": ERR=" << err_seen
                      << " expected " << expected_err << "\n";
            ok = false;
        }
        bool expected_svreq = (op & 0x80) != 0;
        if (svreq_seen != expected_svreq) {
            std::cerr << "FAIL " << name << ": SVREQ=" << svreq_seen
                      << " expected " << expected_svreq << "\n";
            ok = false;
        }
        if (actual != expected) {
            std::cerr << "FAIL " << name << ": stack mismatch\n";
            std::cerr << "  expected:";
            for (uint8_t b : expected)
                std::cerr << " " << std::hex << static_cast<int>(b);
            std::cerr << "\n  actual:  ";
            for (uint8_t b : actual)
                std::cerr << " " << std::hex << static_cast<int>(b);
            std::cerr << std::dec << "\n";
            ok = false;
        }
        if (actual_status != expected_status) {
            std::cerr << "FAIL " << name << ": status " << std::hex
                      << static_cast<int>(actual_status) << " expected "
                      << static_cast<int>(expected_status) << std::dec << "\n";
            ok = false;
        }
        if (!ok)
            ++failures;
    }

    top->final();
    delete top;
    if (failures) {
        std::cerr << failures << " failure(s) out of " << tests << " vectors\n";
        return 1;
    }
    std::cout << "TEST PASSED: " << tests << " Am9512 vectors\n";
    return 0;
}